const CHAPTER_ICON = ['book','shield','shield','bug','warning','bug','hands','spray','check','shield','check','check','check','book','truck','check','pot','pot','book','hands','glove','thermometer','check','snow','snow','snow','hands','snow','spray','spray','spray','spray','shield','warning','flame','bolt','warning','warning','warning','flame','glove','cross','book','check'];
function noteIcon() {
  const k = CHAPTER_ICON[studyChap] || 'book';
  return `<div class="note-icon" aria-hidden="true"><svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">${NOTE_ICONS[k]}</svg></div>`;
}
const NOTE_IDX = { ar: 1, en: 2, hi: 3, bn: 4, id: 5, ne: 6, te: 2 }; // te: English until study notes are translated
const NOTE_TITLE_IDX = { ar: 0, en: 1, hi: 2, bn: 3, id: 4, ne: 5, te: 1 };
let studyChap = 0;
function showStudy() {
  if (!studyLang) studyLang = lang;
  renderStudy();
  showScreen('study');
  window.scrollTo(0, 0);
}
function noteText(row, L) { return escHtml(row[NOTE_IDX[L]]); }
function renderNoteRow(row, L) {
  const t = row[0], txt = noteText(row, L), dir = ' dir="auto"';
  if (t === 'h2') return `<h3 class="note-h2"${dir}>${txt}</h3>`;
  if (t === 'h3') return `<h4 class="note-h3"${dir}>${txt}</h4>`;
  if (t === 'n') return `<div class="note-callout"${dir}>${txt}</div>`;
  return `<p class="note-p"${dir}>${txt}</p>`; // p
}
function renderNoteBlock(chap, L) {
  // groups consecutive li rows into one list
  let out = '', inList = false;
  for (const row of chap.r) {
    if (row[0] === 'li') {
      if (!inList) { out += '<ul class="note-ul">'; inList = true; }
      out += `<li dir="auto">${noteText(row, L)}</li>`;
    } else {
      if (inList) { out += '</ul>'; inList = false; }
      out += renderNoteRow(row, L);
    }
  }
  if (inList) out += '</ul>';
  return out;
}
function renderStudy() {
  const chipDefs = [['all', STUDY_T[lang].all], ...REV_LANGS];
  document.getElementById('study-chips').innerHTML = chipDefs.map(([L, name]) =>
    `<button class="lang-btn${(studyLang === L) ? ' active' : ''}" data-sl="${L}">${escHtml(name)}</button>`).join('');
  document.querySelectorAll('#study-chips [data-sl]').forEach(b =>
    b.addEventListener('click', () => { studyLang = b.dataset.sl; renderStudy(); }));

  const titleL = studyLang === 'all' ? 'ar' : studyLang;
  const opts = STUDY_NOTES.map((c, i) =>
    `<option value="${i}"${i === studyChap ? ' selected' : ''}>${i + 1}. ${escHtml(c.t[NOTE_TITLE_IDX[titleL]])}</option>`).join('');
  const nav = `<div class="note-nav">` +
    `<button class="btn btn-secondary btn-small" id="note-prev"${studyChap === 0 ? ' disabled' : ''}>${escHtml(STUDY_T[lang].prev)}</button>` +
    `<select id="note-sel" class="note-sel">${opts}</select>` +
    `<button class="btn btn-secondary btn-small" id="note-next"${studyChap >= STUDY_NOTES.length - 1 ? ' disabled' : ''}>${escHtml(STUDY_T[lang].next)}</button>` +
    `</div>`;
  const chap = STUDY_NOTES[studyChap];
  let body;
  if (studyLang === 'all') {
    body = REV_LANGS.map(([L, name]) =>
      `<section class="note-lang-sec"><div class="rev-lbl">${escHtml(name)}</div>${noteIcon()}<h2 class="note-title" dir="auto">${escHtml(chap.t[NOTE_TITLE_IDX[L]])}</h2>${renderNoteBlock(chap, L)}</section>`).join('');
  } else {
    body = `${noteIcon()}<h2 class="note-title" dir="auto">${escHtml(chap.t[NOTE_TITLE_IDX[studyLang]])}</h2>${renderNoteBlock(chap, studyLang)}`;
  }
  document.getElementById('study-body').innerHTML =
    `<div class="card note-wrap">${nav}<div class="note-content">${body}</div></div>`;
  const go = i => { studyChap = Math.max(0, Math.min(STUDY_NOTES.length - 1, i)); renderStudy(); window.scrollTo(0, 0); };
  document.getElementById('note-sel').addEventListener('change', e => go(+e.target.value));
  document.getElementById('note-prev').addEventListener('click', () => go(studyChap - 1));
  document.getElementById('note-next').addEventListener('click', () => go(studyChap + 1));
}
